#!/usr/bin/env python3
import json, os, subprocess, sys, tempfile
checks = [a.split(":", 1) for a in sys.argv[1:]]          # (reply | files, check)
e = json.load(sys.stdin)
event, ti = e.get("hook_event_name"), e.get("tool_input") or {}


def run(kind, path, shown=None):
    out = []
    for k, c in checks:
        if k == kind:
            r = subprocess.run([c, path], capture_output=True, text=True)
            if r.returncode:
                out.append((r.stdout + r.stderr).strip().replace(path, shown or path))
    return out


def temp(text, suffix):
    f = tempfile.NamedTemporaryFile("w", suffix=suffix, delete=False)
    f.write(text)
    f.close()
    return f.name


def workspace():
    out = []
    for d, dirs, fs in os.walk("/workspace"):
        dirs[:] = [x for x in dirs if not x.startswith(".") and x != "node_modules"]
        for f in fs:
            out += run("files", os.path.join(d, f))
    return out


if event == "PreToolUse" and ti.get("file_path"):
    p, text = ti["file_path"], ti.get("content")
    if text is None:
        text = open(p, encoding="utf-8").read() if os.path.exists(p) else ""
        text = text.replace(ti.get("old_string", ""), ti.get("new_string", ""), 1)
    t = temp(text, os.path.splitext(p)[1])
    msgs = run("files", t, p)
    os.unlink(t)
    if msgs:
        print(json.dumps({"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny",
                                                 "permissionDecisionReason": "\n".join(msgs)}}))
elif event == "PostToolUse":
    p = ti.get("file_path")
    msgs = run("files", p) if p and os.path.exists(p) else workspace()
    if msgs:
        print("\n".join(msgs), file=sys.stderr)
        sys.exit(2)
elif event == "Stop":
    t = temp(e.get("last_assistant_message") or "", ".txt")
    msgs = run("reply", t) + workspace()
    os.unlink(t)
    if msgs:
        print(json.dumps({"decision": "block", "reason": "\n".join(msgs)}))
